 group.innerHTML=`<title>查詢截面 x=${nf(x,5)}m</title><line x1="${X}" y1="32" x2="${X}" y2="268" stroke="#8f4146" stroke-width="1.5" stroke-dasharray="4 4" vector-effect="non-scaling-stroke"/><circle cx="${X}" cy="186" r="7" fill="white" stroke="#8f4146" stroke-width="2" vector-effect="non-scaling-stroke"/>`;svg.append(group);
