  const fs=Math.max(1,Math.min(2.5,900/(svg.clientWidth||Math.min(900,window.innerWidth||900)))),left=Math.min(140,48*fs),span=872-left;svg.dataset.plotLeft=String(left);svg.dataset.plotSpan=String(span);
  const X=x=>left+x/model.length*span,Y=v=>76-v*factor/amp*54,path=(data,values)=>values.map((v,i)=>`${i?'L':'M'}${X(data[i].x).toFixed(3)},${Y(v).toFixed(3)}`).join('');
