 $('plot-position').max=String(L);$('plot-position').value=plotProbe===null?'':num(plotProbe);$('plot-side').value=plotSide;
 slider.max=String(L);slider.step=String(L/1000||.001);slider.disabled=!result;slider.value=String(plotProbe??0);slider.setAttribute('aria-valuetext',info?'查詢x='+nf(plotProbe,5)+'m'+(info.row?'，包絡採站x='+nf(info.x,5)+'m':''):'等待有效分析結果');
