 svg.addEventListener('pointerdown',e=>{if(!result||e.isPrimary===false||(e.button!==undefined&&e.button!==0))return;plotDrag={svg,id:e.pointerId,startX:e.clientX,startY:e.clientY,active:false};try{svg.setPointerCapture?.(e.pointerId);}catch{}});
