function zoomAt(scale,pixel=.5){const old=zoom.scale,center=zoom.left+pixel/old;zoom.scale=Math.max(1,Math.min(8,scale));zoom.left=Math.max(0,Math.min(1-1/zoom.scale,center-pixel/zoom.scale));renderDiagram();}$('zoom-in').onclick=()=>zoomAt(zoom.scale*1.3);$('zoom-out').onclick=()=>zoomAt(zoom.scale/1.3);$('zoom-reset').onclick=()=>{zoom={scale:1,left:0};renderDiagram();};const svg=$('beam-diagram'),pointers=new Map();let drag=null,pinch=null;svg.addEventListener('wheel',e=>{e.preventDefault();const r=svg.getBoundingClientRect();zoomAt(zoom.scale*(e.deltaY<0?1.15:1/1.15),Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)));},{passive:false});svg.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});svg.setPointerCapture(e.pointerId);drag={x:e.clientX,left:zoom.left};if(pointers.size===2){const p=[...pointers.values()];pinch={distance:Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y),scale:zoom.scale};}});svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){const p=[...pointers.values()];zoomAt(pinch.scale*Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y)/Math.max(1,pinch.distance));}else if(drag){zoom.left=Math.max(0,Math.min(1-1/zoom.scale,drag.left-(e.clientX-drag.x)/(svg.getBoundingClientRect().width*.872*zoom.scale)));renderDiagram();}});for(const event of ['pointerup','pointercancel'])svg.addEventListener(event,e=>{pointers.delete(e.pointerId);drag=null;pinch=null;});
